import test from'node:test';import assert from'node:assert/strict';import{readFile}from'node:fs/promises';import{createHash}from'node:crypto';import{adaptContextNavigation,UPSTREAM_CLIENT_SHA256,SUITE_PACKAGE}from'./context-navigation-adapter.mjs';
test('unknown upstream is rejected, never broadly rewritten',()=>{assert.throws(()=>adaptContextNavigation('function jo(){}'),/Unreviewed/);});
test('reviewed upstream gets formal navigation and original form retarget only',async()=>{const path=new URL('./node_modules/dsh-context/lib/client.js',import.meta.url);const original=await readFile(path,'utf8');assert.equal(createHash('sha256').update(original).digest('hex'),UPSTREAM_CLIENT_SHA256);const patched=adaptContextNavigation(original);assert.ok(patched.includes(`openBundle('${SUITE_PACKAGE}')`));assert.ok(!patched.includes('function jo(e=document'));assert.ok(patched.includes('inject:[`slots`,`locale`,`pluginNavigation`]'));assert.ok(patched.includes("key:'@forcemind/dsh-atelier-suite',locale:Au,inject:d"));assert.ok(patched.includes('r.attach(i.get(Au))'));assert.ok(patched.includes('Apache-2.0'));assert.ok(!patched.includes('sourceMappingURL=client.js.map'));assert.equal(createHash('sha256').update(await readFile(path,'utf8')).digest('hex'),UPSTREAM_CLIENT_SHA256);});
